// @FIGURE_CODE_BEGIN
(function(){
  var ANGLE = 17 * Math.PI / 180;
  var DX = Math.cos(ANGLE);
  var DY = -Math.sin(ANGLE);
  var V_LEN = 110;
  var W = 700, H = 550;

  var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
  draw.viewbox(0, 0, W, H);

  var COLORS = {
    three: '#1a3a6b',
    v: '#e8710a',
    half: '#0d9488',
    neg: '#dc2626',
    live: '#8b5cf6'
  };

  var currentK = 1;
  var overlayMode = false;

  // Groups
  var stackedGroup = draw.group();
  var overlayGroup = draw.group();
  overlayGroup.hide();

  // ── Arrow helper ──
  function makeArrow(g, tailX, tailY, len, color, label, reversed, dotAtTail) {
    var dirX = reversed ? -DX : DX;
    var dirY = reversed ? -DY : DY;
    var headX = tailX + len * dirX;
    var headY = tailY + len * dirY;
    var dotX = dotAtTail ? tailX : headX;
    var dotY = dotAtTail ? tailY : headY;

    // Line
    var line = g.line(tailX, tailY, headX, headY).stroke({color: color, width: 2.5, linecap:'round'});

    // Dot
    var dot = g.circle(7).center(dotX, dotY).fill('#111');

    // Arrowhead
    var aSize = 10;
    var perpX = -dirY, perpY = dirX;
    var bx = headX - dirX * aSize, by = headY - dirY * aSize;
    var p1 = [headX, headY];
    var p2 = [bx + perpX * aSize * 0.4, by + perpY * aSize * 0.4];
    var p3 = [bx - perpX * aSize * 0.4, by - perpY * aSize * 0.4];
    var head = g.polygon([p1,p2,p3].map(function(p){return p[0]+','+p[1]}).join(' ')).fill(color);

    // Label
    var lx = headX + dirX * 14 + perpX * 10;
    var ly = headY + dirY * 14 + perpY * 10;
    if (reversed) { lx = headX + dirX * 14 - perpX * 10; ly = headY + dirY * 14 - perpY * 10; }
    var txt = g.text(label).move(lx, ly).font({size: 14, weight: 'bold', family: 'serif'}).fill('#111')
      .attr({'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round'});

    return {line:line, dot:dot, head:head, txt:txt, group:g};
  }

  // ── Stacked layout ──
  var stackedArrows = {};
  var liveStacked = null;
  var liveLabel = null;

  function buildStacked() {
    stackedGroup.clear();
    // 3v
    makeArrow(stackedGroup, 25, 140, 3*V_LEN, COLORS.three, '3v', false, true);
    // v
    makeArrow(stackedGroup, 25, 260, V_LEN, COLORS.v, 'v', false, true);
    // ½v
    makeArrow(stackedGroup, 25, 350, 0.5*V_LEN, COLORS.half, '½v', false, true);
    // -v (dot at right, arrowhead at left)
    makeArrow(stackedGroup, 230, 440, V_LEN, COLORS.neg, '−v', true, true);
    // Live k·v
    buildLiveStacked();
  }

  function buildLiveStacked() {
    if (liveStacked) { liveStacked.line.remove(); liveStacked.dot.remove(); liveStacked.head.remove(); liveStacked.txt.remove(); }
    if (liveLabel) liveLabel.remove();
    var k = currentK;
    var tailX = 25, tailY = 510;
    var len = Math.abs(k) * V_LEN;
    var reversed = k < 0;
    if (Math.abs(k) < 0.01) len = 0;

    var dirX = reversed ? -DX : DX;
    var dirY = reversed ? -DY : DY;
    var headX = tailX + len * dirX;
    var headY = tailY + len * dirY;

    var line = stackedGroup.line(tailX, tailY, headX, headY).stroke({color: COLORS.live, width: 3, linecap:'round'});
    var dot = stackedGroup.circle(7).center(tailX, tailY).fill('#111');

    var head = null;
    if (len > 2) {
      var aSize = 10;
      var perpX = -dirY, perpY = dirX;
      var bx = headX - dirX * aSize, by = headY - dirY * aSize;
      head = stackedGroup.polygon([[headX,headY],[bx+perpX*aSize*0.4,by+perpY*aSize*0.4],[bx-perpX*aSize*0.4,by-perpY*aSize*0.4]].map(function(p){return p[0]+','+p[1]}).join(' ')).fill(COLORS.live);
    }

    var kStr = k === Math.round(k) ? String(k) : k.toFixed(1);
    var lbl = stackedGroup.text('k·v  (k = ' + kStr + ')').move(tailX + 10, tailY + 16).font({size: 12, family:'sans-serif'}).fill(COLORS.live)
      .attr({'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round'});

    liveStacked = {line:line, dot:dot, head:head, txt:lbl};
  }

  // ── Overlay layout ──
  var OX = 320, OY = 300;

  function buildOverlay() {
    overlayGroup.clear();

    // Faint reference arrows with ticks
    var refs = [
      {k: 3, color: COLORS.three, label: '3v'},
      {k: 1, color: COLORS.v, label: 'v'},
      {k: 0.5, color: COLORS.half, label: '½v'},
      {k: -1, color: COLORS.neg, label: '−v'}
    ];

    refs.forEach(function(r) {
      var len = Math.abs(r.k) * V_LEN;
      var dirX = r.k < 0 ? -DX : DX;
      var dirY = r.k < 0 ? -DY : DY;
      var hx = OX + len * dirX, hy = OY + len * dirY;
      overlayGroup.line(OX, OY, hx, hy).stroke({color: r.color, width: 1.5, opacity: 0.35, linecap:'round'});
      // Tick mark at head
      var perpX = -dirY, perpY = dirX;
      overlayGroup.line(hx - perpX*6, hy - perpY*6, hx + perpX*6, hy + perpY*6).stroke({color: r.color, width: 2, opacity: 0.7});
      // Label
      var lx = hx + dirX * 12 + perpX * 12;
      var ly = hy + dirY * 12 + perpY * 12;
      overlayGroup.text(r.label).move(lx, ly).font({size: 11, family:'serif'}).fill(r.color).opacity(0.7)
        .attr({'paint-order':'stroke', stroke:'#fff', 'stroke-width':2, 'stroke-linejoin':'round'});
    });

    // Origin dot
    overlayGroup.circle(8).center(OX, OY).fill('#111');

    // Live arrow
    buildLiveOverlay();
  }

  var liveOverlay = null;

  function buildLiveOverlay() {
    if (liveOverlay) { liveOverlay.line.remove(); liveOverlay.head.remove(); liveOverlay.lbl.remove(); }
    var k = currentK;
    var len = Math.abs(k) * V_LEN;
    var reversed = k < 0;
    if (Math.abs(k) < 0.01) len = 0;

    var dirX = reversed ? -DX : DX;
    var dirY = reversed ? -DY : DY;
    var hx = OX + len * dirX, hy = OY + len * dirY;

    var line = overlayGroup.line(OX, OY, hx, hy).stroke({color: COLORS.live, width: 3.5, linecap:'round'});
    var head = null;
    if (len > 2) {
      var aSize = 11;
      var perpX = -dirY, perpY = dirX;
      var bx = hx - dirX * aSize, by = hy - dirY * aSize;
      head = overlayGroup.polygon([[hx,hy],[bx+perpX*aSize*0.4,by+perpY*aSize*0.4],[bx-perpX*aSize*0.4,by-perpY*aSize*0.4]].map(function(p){return p[0]+','+p[1]}).join(' ')).fill(COLORS.live);
    }

    var kStr = k === Math.round(k) ? String(k) : k.toFixed(1);
    var lbl = overlayGroup.text('k·v (k=' + kStr + ')').move(hx + 12, hy - 14).font({size: 12, weight:'bold', family:'sans-serif'}).fill(COLORS.live)
      .attr({'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round'});

    liveOverlay = {line:line, head:head, lbl:lbl};
  }

  // ── Update functions ──
  window.update_scalarK = function(v) {
    currentK = v;
    if (overlayMode) { buildLiveOverlay(); } else { buildLiveStacked(); }
  };

  window.toggle_layoutMode = function(on) {
    overlayMode = on;
    if (on) {
      stackedGroup.hide();
      overlayGroup.show();
      buildOverlay();
    } else {
      overlayGroup.hide();
      stackedGroup.show();
      buildStacked();
    }
  };

  // ── Demo steps ──
  var steps = [
    {title:'Match the reference', narration:'At k = 1 the live arrow exactly overlaps the orange reference v in length and heading — this is the baseline every other multiple is measured against.', k:1, overlay:false},
    {title:'Stretch and shrink', narration:'Sweep k up to 3 and the live arrow grows to match the navy 3v; sweep down to 0.5 and it shrinks to the teal (1/2)v. Positive k only changes length, never direction.', k:3, overlay:false},
    {title:'Cross zero and flip', narration:'Drag k through 0 to −1: the arrow first collapses to its tail dot, then re-emerges pointing the opposite way, landing on the red −v. A negative scalar reverses the heading while |k| still sets the length.', k:-1, overlay:false},
    {title:'See the line of action', narration:'Switch to the shared-tail overlay: every arrow now starts at one origin, and as you move k the live head slides along a single straight line, passing exactly through the 3v, v, (1/2)v ticks on one side and the −v tick on the other.', k:1, overlay:true}
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = i;
    var s = steps[i];
    currentK = s.k;
    overlayMode = s.overlay;
    document.getElementById('scalarKInput').value = s.k;
    document.getElementById('scalarKVal').value = s.k;
    document.getElementById('layoutModeInput').checked = s.overlay;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = (i+1) + ' / ' + steps.length;
    if (s.overlay) {
      stackedGroup.hide(); overlayGroup.show(); buildOverlay();
    } else {
